function tarjanSCC(nodes, edges){
  var idx={}; nodes.forEach(function(n,i){idx[n]=i;});
  var index=0, stack=[], onstack={}, low={}, num={}, result=[];
  var adj={}; nodes.forEach(function(n){adj[n]=[];});
  edges.forEach(function(e){ adj[e[0]].push(e[1]); });
  function sc(v){
    num[v]=index; low[v]=index; index++; stack.push(v); onstack[v]=true;
    adj[v].forEach(function(w){
      if(num[w]===undefined){ sc(w); low[v]=Math.min(low[v],low[w]); }
      else if(onstack[w]){ low[v]=Math.min(low[v],num[w]); }
    });
    if(low[v]===num[v]){ var comp=[]; var w; do{ w=stack.pop(); onstack[w]=false; comp.push(w); }while(w!==v); result.push(comp); }
  }
  nodes.forEach(function(n){ if(num[n]===undefined) sc(n); });
  return result;
}
var EXPORTS={tarjanSCC:tarjanSCC};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.TarjanSCCForgePure = EXPORTS; }
